function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 500) return 'grid needs 1 to 500 rows.';
  const n = grid.length;
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'grid must be square: n rows of n cells.';
    if (row.some((v) => v !== 0 && v !== 1)) return 'grid cells are 0 or 1.';
  }
  return null;
}

