function largestIsland(grid) {
  const n = grid.length;
  const labels = grid.map((row) => row.slice());
  const area = new Map();
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let label = 2;
  let best = 0;
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (labels[r][c] !== 1) continue;
      let size = 0;
      const stack = [[r, c]];
      labels[r][c] = label;
      while (stack.length > 0) {
        const [cr, cc] = stack.pop();
        size++;
        for (const [dr, dc] of directions) {
          const nr = cr + dr;
          const nc = cc + dc;
          if (nr >= 0 && nr < n && nc >= 0 && nc < n && labels[nr][nc] === 1) {
            labels[nr][nc] = label;
            stack.push([nr, nc]);
          }
        }
      }
      area.set(label, size);
      best = Math.max(best, size);
      label++;
    }
  }
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (labels[r][c] !== 0) continue;
      const touching = new Set();
      for (const [dr, dc] of directions) {
        const nr = r + dr;
        const nc = c + dc;
        if (nr >= 0 && nr < n && nc >= 0 && nc < n && labels[nr][nc] > 1) {
          touching.add(labels[nr][nc]);
        }
      }
      let size = 1;
      for (const id of touching) size += area.get(id);
      best = Math.max(best, size);
    }
  }
  return best;
}

