function largestIsland(grid) {
  // Try every single flip (and no flip), measuring the largest island from scratch each time.
  const n = grid.length;
  const largest = (cells) => {
    const visited = cells.map((row) => row.map(() => false));
    let top = 0;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        if (cells[i][j] !== 1 || visited[i][j]) continue;
        visited[i][j] = true;
        const queue = [[i, j]];
        for (let head = 0; head < queue.length; head++) {
          const [r, c] = queue[head];
          for (const [a, b] of [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]]) {
            if (a >= 0 && a < n && b >= 0 && b < n && cells[a][b] === 1 && !visited[a][b]) {
              visited[a][b] = true;
              queue.push([a, b]);
            }
          }
        }
        top = Math.max(top, queue.length);
      }
    }
    return top;
  };
  let answer = largest(grid);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] !== 0) continue;
      const copy = grid.map((row) => row.slice());
      copy[i][j] = 1;
      answer = Math.max(answer, largest(copy));
    }
  }
  return answer;
}

