function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const density = rand() < 0.1 ? (rand() < 0.5 ? 0 : 1) : 0.25 + rand() * 0.5;
  return [Array.from({ length: n }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)))];
}
